    if ((body_primary == NULL) || (body_secondary == NULL) || (ref_primary == NULL) ||
        (ref_secondary == NULL) || (check_body == NULL) || (check_ref == NULL) ||
        (c_bi == NULL) || (alignment == NULL)) {
        return ADCS_E_NULL;
    }

    *c_bi = adcs_mat3_identity();
    *alignment = 0.0;

    st = adcs_triad(body_primary, body_secondary, ref_primary, ref_secondary, c_bi);
    if (st != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return st;
    }

    if (adcs_vec3_normalize(check_ref, ADCS_EPS_NORM, &ref_n) != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &body_n) != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return ADCS_E_DEGENERATE;
    }

    *alignment = ADCS_CLAMP(adcs_vec3_dot(&ref_n, &body_n), -1.0, 1.0);
    return ADCS_OK;
}

